## @SpringBootTest with Real Server

```java
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Testcontainers
@Transactional  // Rollback after each test
class OrderIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:15")
        .withDatabaseName("testdb")
        .withUsername("test")
        .withPassword("test");

    @DynamicPropertySource
    static void configureProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Autowired
    private TestRestTemplate restTemplate;  // Automatic with RANDOM_PORT

    @Autowired
    private UserRepository userRepository;  // For setup/teardown

    @Autowired
    private OrderRepository orderRepository;

    private User testUser;
    private String authToken;

    @BeforeEach
    void setup() {
        testUser = userRepository.save(User.builder()
            .email("test@example.com")
            .password("$2a$10$hashhashhash")  // BCrypt encoded
            .role("USER")
            .build());
        authToken = authenticateAndGetToken("test@example.com", "password");
    }

    @Test
    void shouldCreateAndRetrieveOrderEndToEnd() {
        // Create order via HTTP
        CreateOrderRequest request = CreateOrderRequest.builder()
            .items(List.of(new OrderItem("item-1", 2, new BigDecimal("29.99"))))
            .shippingAddress("123 Test St")
            .build();

        ResponseEntity<OrderResponse> createResponse = restTemplate
            .withBasicAuth("test@example.com", "password")
            .postForEntity("/api/orders", request, OrderResponse.class);

        assertThat(createResponse.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        Long orderId = createResponse.getBody().getId();
        assertThat(orderId).isNotNull();

        // Retrieve order via HTTP
        ResponseEntity<OrderResponse> getResponse = restTemplate
            .withBasicAuth("test@example.com", "password")
            .getForEntity("/api/orders/" + orderId, OrderResponse.class);

        assertThat(getResponse.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(getResponse.getBody().getStatus()).isEqualTo("PENDING");
    }

    @Test
    void shouldReturn401WhenNotAuthenticated() {
        ResponseEntity<String> response = restTemplate
            .getForEntity("/api/orders", String.class);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);
    }
}
```

## WebTestClient (Reactive / Fluent API)

```java
@SpringBootTest(webEnvironment = RANDOM_PORT)
class OrderWebTestClientTest {

    @Autowired
    private WebTestClient webTestClient;

    @Test
    void shouldReturnOrders() {
        webTestClient.get()
            .uri("/api/orders")
            .header("Authorization", "Bearer " + authToken)
            .exchange()
            .expectStatus().isOk()
            .expectHeader().contentType(MediaType.APPLICATION_JSON)
            .expectBody()
            .jsonPath("$.content").isArray()
            .jsonPath("$.totalElements").isNumber();
    }

    @Test
    void shouldHandleHighLoad() {
        // Test with multiple concurrent requests:
        Flux.range(1, 10)
            .flatMap(i -> webTestClient.get().uri("/api/orders").exchange())
            .blockLast();
        // No assertion failure = all requests handled successfully
    }
}
```

